import sys

def cs_brute(cands, target):
    res = []
    def dfs(i, remain, path):
        if remain == 0:
            res.append(path[:])
            return
        if i >= len(cands):
            return
        x = cands[i]
        if x > remain:
            return
        # 不取
        dfs(i + 1, remain, path)
        # 取
        path.append(x)
        dfs(i, remain - x, path)
        path.pop()
    dfs(0, target, [])
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    cands = list(map(int, data[1:1 + n]))
    target = int(data[1 + n])
    res = cs_brute(cands, target)
    for comb in res:
        print(' '.join(map(str, comb)))

import sys

def cs_opt(cands, target):
    res = []
    def dfs(i, remain, path):
        if remain == 0:
            res.append(path[:])
            return
        for j in range(i, len(cands)):
            x = cands[j]
            if x > remain:
                break
            path.append(x)
            dfs(j, remain - x, path)
            path.pop()
    dfs(0, target, [])
    return sorted(res)

if __name__ == '__main__':
