    if not data:
        sys.exit(0)
    n = int(data[0])
    cands = list(map(int, data[1:1 + n]))
    target = int(data[1 + n])
    res = cs_opt(cands, target)
    for comb in res:
        print(' '.join(map(str, comb)))

import sys

def cs_best(cands, target):
    dp = [[] for _ in range(target + 1)]
    dp[0] = [[]]
    for x in cands:
        for r in range(x, target + 1):
            for pre in dp[r - x]:
                dp[r].append(pre + [x])
    return sorted([list(map(int, comb)) for comb in dp[target]])

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    cands = list(map(int, data[1:1 + n]))
    target = int(data[1 + n])
    res = cs_best(cands, target)
    for comb in res:
        print(' '.join(map(str, comb)))
